import React, { useState } from 'react';
import Modal from 'react-modal';
import styled from 'styled-components';

const Equipment = ({ equipment, handleSelect, selectedItems = [] }) => {
  const [modalItem, setModalItem] = useState(null);

  const openModal = (item) => setModalItem(item);
  const closeModal = () => setModalItem(null);

  const isSelected = (item) =>
    selectedItems.some((selected) => selected.id === item.id);

  return (
    <>
      <div className="grid">
        {equipment.map((item) => (
          <div key={item.id} onClick={() => openModal(item)}>
            <img src={item.image_url} alt={item.name} style={{ width: '150px', height: '150px' }} />
            <h3>{item.name}</h3>
            <p>Brand: {item.brand}</p>
            <p>Price: ${item.price}</p>
          </div>
        ))}
      </div>

      {modalItem && (
        <Modal
          isOpen={!!modalItem}
          onRequestClose={closeModal}
          style={{ overlay: {}, content: { padding: '20px' } }}
        >
          <div>
            <h2>{modalItem.name}</h2>
            <img src={modalItem.image_url} alt={modalItem.name} style={{ maxHeight: '300px' }} />
            <p><strong>Brand:</strong> {modalItem.brand}</p>
            <p><strong>Price:</strong> ${modalItem.price}</p>

            {/* Fix for Details */}
            {modalItem.details && Array.isArray(modalItem.details) && modalItem.details.length > 0 ? (
              <div>
                <h4>Details:</h4>
                <ul>
                  {modalItem.details.map((detail, index) => (
                    <li key={index}>{detail}</li>
                  ))}
                </ul>
              </div>
            ) : (
              <p><strong>Details:</strong> {typeof modalItem.details === 'string' ? modalItem.details : 'No details available'}</p>
            )}

            {/* Fix for Tech Specs */}
            {modalItem.tech_specs && Object.keys(modalItem.tech_specs).length > 0 && (
              <div>
                <h4>Tech Specs:</h4>
                <ul>
                  {Object.entries(modalItem.tech_specs).map(([key, value], index) => (
                    <li key={index}><strong>{key}:</strong> {value}</li>
                  ))}
                </ul>
              </div>
            )}

            {modalItem.link && (
              <div>
                <a href={modalItem.link} target="_blank" rel="noopener noreferrer">
                  View Product Page
                </a>
              </div>
            )}

            <button onClick={closeModal}>Close</button>
          </div>
        </Modal>
      )}
    </>
  );
};

export default Equipment;
